class OverdueInvoiceSpec {
  isSatisfiedBy(invoice: Invoice): boolean {
    const now = new Date();
    return (
      invoice.status === 'unpaid' &&
      invoice.dueDate < now
    );
  }

  and(other: Specification<Invoice>) {
    return new AndSpecification(this, other);
  }
}

class OrderFactory {
  static createFromQuote(
    quote: Quote,
    shippingAddress: Address
  ): Order {
    const order = new Order(generateId());
    for (const line of quote.lines) {
      order.addItem(
        line.productId,
        line.quantity,
        line.negotiatedPrice
      );
    }
    order.setShipping(shippingAddress);
    return order;
  }
}

// Shipping context
interface InventoryService {
  checkAvailability(
    sku: string,
    qty: number
  ): Promise<boolean>;
}

// Implementation adapts Inventory API
class InventoryServiceAdapter
  implements InventoryService {
  async checkAvailability(
    sku: string, qty: number
  ): Promise<boolean> {
    const res = await this.inventoryApi
      .getStockLevel({ itemCode: sku });
    return res.availableUnits >= qty;
  }
}

class TransferService {
  async transfer(
    fromId: string,
    toId: string,
    amount: Money
  ): Promise<void> {
    const from = await this.accountRepo
      .findById(fromId);
    const to = await this.accountRepo
      .findById(toId);
    from.debit(amount);
    to.credit(amount);
    await this.accountRepo.save(from);
    await this.accountRepo.save(to);
  }
}

class OrderConfirmedHandler {
  async handle(
    event: OrderConfirmed
  ): Promise<void> {
    const existing = await this.ledgerRepo
      .findByEventId(event.eventId);
    if (existing) return;

    const entry = LedgerEntry.create(
      event.orderId,
      event.total,
      event.eventId
    );
    await this.ledgerRepo.save(entry);
  }
}

class SqlOrderRepository {
  async save(order: Order): Promise<void> {
    const result = await this.db.query(
      `UPDATE orders
       SET data = $1, version = $2
       WHERE id = $3 AND version = $4`,
      [
        serialize(order),
        order.version + 1,
        order.id,
        order.version
      ]
    );
    if (result.rowCount === 0)
      throw new ConcurrencyError(order.id);
  }
}

// Our domain model
interface Product {
  sku: string;
  name: string;
  price: Money;
}

// ACL translating legacy ERP
class ErpProductAdapter {
  constructor(
    private erpClient: ErpSoapClient
  ) {}

  async getProduct(
    sku: string
  ): Promise<Product> {
    const raw = await this.erpClient
      .fetchItem({ ITEM_NO: sku });
    return {
      sku: raw.ITEM_NO,
      name: raw.DESC_LONG,
      price: new Money(
        raw.UNIT_PRC / 100,
        raw.CCY_CD
      ),
    };
  }
}
